Given a string s and a screen containing lowercase English alphabets from a to z arranged in a fixed grid, movement between adjacent cells is allowed using a remote control with UP, DOWN, LEFT, RIGHT keys. The characters are arranged in the following grid: Initially, the pointer is placed at the cell containing 'a'. The remote also has an OK button, used to select the current character. Find the minimum number of moves required to type the string s in order, where each movement to an adjacent cell and each OK press both count as one move.Examples: Input: s = "abc"Output: 5Explanation: Remote's position is at 'a' initially. So 'a' -> 'b' = 1 step,'b'-> 'c'= 1 step. Three OK moves will also be needed to print the three characters.Input: s = "a"Output: 1Explanation: Already at 'a', only OK press is required.Try It YourselfTable of Content[Naive Approach] BFS (Matrix Traversal) - O(26 × N) Time and O(26) Space[Expected Approach] Direct Coordinate Simulation - O(N) Time and O(1) Space[Naive Approach] BFS (Matrix Traversal) - O(26 × N) Time and O(26) SpaceThe grid is treated as an unweighted graph where each cell represents a node and movement between adjacent cells has equal cost. Hence, the shortest path between any two characters can be found using BFS. For each character in the string, BFS is used to compute the minimum distance from the current position to the target character. After reaching the character, one additional move is added for pressing the OK button. This process is repeated for all characters.Represent the grid as a 2D matrix.Start from position of 'a'.For each character in S:Find current and target positions.Run BFS to get shortest distance.Add distance + 1 (OK press) to answer and update current position.
            C++

    #include <bits/stdc++.h>
using namespace std;

// 2D grid of characters a-z
vector<vector<char>> grid = {
    {'a','b','c','d','e'},
    {'f','g','h','i','j'},
    {'k','l','m','n','o'},
    {'p','q','r','s','t'},
    {'u','v','w','x','y'},
    {'z','\0','\0','\0','\0'}
};

// Directions: UP, LEFT, DOWN, RIGHT
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

// Check valid cell
bool isValid(int x, int y) {
    return (x >= 0 && x < 6 && y >= 0 && y < 5 && grid[x][y] != '\0');
}

// Find position of a character
pair<int,int> find(char ch) {
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 5; j++) {
            if (grid[i][j] == ch) {
                return {i, j};
            }
        }
    }
    return {-1, -1};
}

// BFS to find shortest distance between two cells
int bfs(int sx, int sy, int tx, int ty) {

    queue<array<int,3>> q;
    vector<vector<bool>> vis(6, vector<bool>(5, false));

    // {x, y, distance}
    q.push({sx, sy, 0});
    vis[sx][sy] = true;

    while (!q.empty()) {

        array<int,3> cur = q.front(); q.pop();
        int x = cur[0], y = cur[1], dist = cur[2];

        // destination reached
        if (x == tx && y == ty) {
            return dist;
        }

        // explore all 4 directions
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (isValid(nx, ny) && !vis[nx][ny]) {
                vis[nx][ny] = true;
                q.push({nx, ny, dist + 1});
            }
        }
    }

    return 0;
}

// Function to find total moves
int findPath(string s) {

    // start at 'a'
    pair<int,int> start = find('a');
    int x = start.first, y = start.second;

    int result = 0;

    // traverse string
    for (char c : s) {

        // target position
        pair<int,int> target = find(c);

        // BFS distance
        result += bfs(x, y, target.first, target.second);

        // OK press
        result += 1;

        // update position
        x = target.first;
        y = target.second;
    }

    return result;
}

// Driver
int main() {
    cout << findPath("abc") << endl;
    cout << findPath("a") << endl;
}


