    import java.util.Queue;
import java.util.LinkedList;
class GFG {

    // 2D grid of characters a-z
    static char[][] grid = {
        {'a','b','c','d','e'},
        {'f','g','h','i','j'},
        {'k','l','m','n','o'},
        {'p','q','r','s','t'},
        {'u','v','w','x','y'},
        {'z','\0','\0','\0','\0'}
    };

    // Directions: UP, LEFT, DOWN, RIGHT
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, -1, 0, 1};

    // Check valid cell
    static boolean isValid(int x, int y) {
        return (x >= 0 && x < 6 && y >= 0 && y < 5 && grid[x][y] != '\0');
    }

    // Find position of a character
    static int[] find(char ch) {
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                if (grid[i][j] == ch) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1};
    }

    // BFS to find shortest distance between two cells
    static int bfs(int sx, int sy, int tx, int ty) {

        Queue<int[]> q = new LinkedList<>();
        boolean[][] vis = new boolean[6][5];

        q.add(new int[]{sx, sy, 0});
        vis[sx][sy] = true;

        while (!q.isEmpty()) {

            int[] cur = q.poll();
            int x = cur[0], y = cur[1], dist = cur[2];

            // destination reached
            if (x == tx && y == ty) {
                return dist;
            }

            // explore all 4 directions
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (isValid(nx, ny) && !vis[nx][ny]) {
                    vis[nx][ny] = true;
                    q.add(new int[]{nx, ny, dist + 1});
                }
            }
        }

        return 0;
    }

    // Function to find total moves
    static int findPath(String s) {

        // start at 'a'
        int[] start = find('a');
        int x = start[0], y = start[1];

        int result = 0;

        // traverse string
        for (char c : s.toCharArray()) {

            // target position
            int[] target = find(c);

            // BFS distance
            result += bfs(x, y, target[0], target[1]);

            // OK press
            result += 1;

            // update position
            x = target[0];
            y = target[1];
        }

        return result;
    }

    public static void main(String[] args) {
        System.out.println(findPath("abc"));
        System.out.println(findPath("a"));
    }
}


