    using System;
using System.Collections.Generic;

class GFG {

    // 2D grid of characters a-z
    static char[,] grid = {
        {'a','b','c','d','e'},
        {'f','g','h','i','j'},
        {'k','l','m','n','o'},
        {'p','q','r','s','t'},
        {'u','v','w','x','y'},
        {'z','\0','\0','\0','\0'}
    };

    // Directions: UP, LEFT, DOWN, RIGHT
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, -1, 0, 1};

    // Check valid cell
    static bool isValid(int x, int y) {
        return (x >= 0 && x < 6 && y >= 0 && y < 5 && grid[x, y] != '\0');
    }

    // Find position of a character
    static (int,int) find(char ch) {
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                if (grid[i, j] == ch) {
                    return (i, j);
                }
            }
        }
        return (-1, -1);
    }

    // BFS to find shortest distance between two cells
    static int bfs(int sx, int sy, int tx, int ty) {

        Queue<(int,int,int)> q = new Queue<(int,int,int)>();
        bool[,] vis = new bool[6,5];

        q.Enqueue((sx, sy, 0));
        vis[sx, sy] = true;

        while (q.Count > 0) {

            var cur = q.Dequeue();
            int x = cur.Item1, y = cur.Item2, dist = cur.Item3;

            // destination reached
            if (x == tx && y == ty) {
                return dist;
            }

            // explore all 4 directions
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (isValid(nx, ny) && !vis[nx, ny]) {
                    vis[nx, ny] = true;
                    q.Enqueue((nx, ny, dist + 1));
                }
            }
        }

        return 0;
    }

    // Function to find total moves
    static int findPath(string s) {

        // start at 'a'
        var start = find('a');
        int x = start.Item1, y = start.Item2;

        int result = 0;

        // traverse string
        foreach (char c in s) {

            // target position
            var target = find(c);

            // BFS distance
            result += bfs(x, y, target.Item1, target.Item2);

            // OK press
            result += 1;

            // update position
            x = target.Item1;
            y = target.Item2;
        }

        return result;
    }

    static void Main() {
        Console.WriteLine(findPath("abc"));
        Console.WriteLine(findPath("a"));
    }
}


